package com.resq.app.core.data.db

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * One row per distinct sender seen on the mesh. Keyed by [senderId]
 * (not an autogenerated row id) so a repeat sighting of the same SOS
 * overwrites in place via [SosLogDao.upsert] instead of growing the log
 * forever — the receiver screen shows "who is out there right now", not
 * a sighting-by-sighting history.
 */
@Entity(tableName = "sos_log")
data class SosLogEntity(
    @PrimaryKey val senderId: Int,
    val message: String,
    val latitude: Double,
    val longitude: Double,
    val batteryPercent: Int,
    val rssi: Int,
    val hopCount: Int,
    val firstSeenAtEpochMillis: Long,
    val lastSeenAtEpochMillis: Long,
    /** True once we've pulled the full [com.resq.app.core.ble.SosRecord], not just the beacon. */
    val hasFullMessage: Boolean,
)
